     "**Remove speaker prefixes**: \"JOHN: Hello\" পরিবর্তন হয়ে \"Hello\" হয়ে যায়। ডিফল্টভাবে বন্ধ থাকে — স্ক্রিপ্ট-স্টাইল টেক্সটে কে কথা বলছে তা দেখানো প্রয়োজন।",
